@tool
extends Node

func run() -> String:
	var d := DirAccess.open("res://")
	if not d.dir_exists("probe_del/nested"):
		d.make_dir_recursive("probe_del/nested")
	var f := FileAccess.open("res://probe_del/nested/a.txt", FileAccess.WRITE)
	if f == null:
		return "S12 file null"
	f.store_string("x")
	f.close()
	if not FileAccess.file_exists("res://probe_del/nested/a.txt"):
		return "S12 write failed"
	var e1 := d.remove_recursive("probe_del")
	return "S12 rc=" + str(e1)
